begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,is_anonymous) values
('91000000-0000-4000-8000-000000000001','upi-owner@example.test',false),
('91000000-0000-4000-8000-000000000002','upi-buyer@example.test',false),
('91000000-0000-4000-8000-000000000003','upi-other@example.test',false);
insert into public.admins values('91000000-0000-4000-8000-000000000001','owner');
update public.payment_settings set enabled=true,upi_id='test@upi',payee_name='Test',activation_mode='instant';
create temporary table upi_orders(kind text primary key,id uuid,reference text);
grant all on upi_orders to authenticated,service_role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
insert into upi_orders select 'first',(x->>'id')::uuid,x->>'reference' from(select public.create_payment_order((select id from public.plans where code='trial'))x)q;
select is((select status from public.payment_orders where id=(select id from upi_orders where kind='first')),'pending','Order starts pending');
select ok((select reference~'^[A-Za-z0-9]{1,35}$' from upi_orders where kind='first'),'Bank reference short alphanumeric');
select is((select amount_paise from public.payment_orders where id=(select id from upi_orders where kind='first')),4900::bigint,'Trigger snapshots exact plan price');
select throws_ok($$insert into public.payment_orders(plan_id)select id from public.plans limit 1$$,'42501',null,'Client cannot insert even with trigger');
select throws_ok($$select private.activate_subscription((select id from upi_orders where kind='first'),'upi_app',null)$$,'42501',null,'Client cannot activate');
select throws_ok($$select public.provider_payment_update((select id from upi_orders where kind='first'),'SUCCESS',4900,'123456789011','fake')$$,'42501',null,'Provider RPC inaccessible to client');
select is(public.report_payment_result((select id from upi_orders where kind='first'),'Status=SUCCESS&txnRef=WRONG&txnId=NEW00001'),'pending','Wrong reference pending');
select is(public.report_payment_result((select id from upi_orders where kind='first'),'Status=SUCCESS'),'pending','Missing transaction pending');
select is(public.report_payment_result((select id from upi_orders where kind='first'),'Status=SUCCESS&txnId=NEW00001'),'paid','Valid client success activates in instant mode');
select is(public.report_payment_result((select id from upi_orders where kind='first'),'Status=SUCCESS&txnId=NEW00001'),'paid','Repeat report idempotent');
select is((select count(*) from public.subscriptions where order_id=(select id from upi_orders where kind='first')),1::bigint,'No duplicate entitlement');
insert into upi_orders select 'second',(x->>'id')::uuid,x->>'reference' from(select public.create_payment_order((select id from public.plans where code='trial'))x)q;
select is(public.report_payment_result((select id from upi_orders where kind='second'),'Status=SUCCESS&txnId=NEW00001'),'pending','Cross-order ID reuse blocked');
select is(public.report_payment_result((select id from upi_orders where kind='second'),'Status=FAILURE'),'failed','Failure status');
select lives_ok($$select public.submit_payment_utr((select id from upi_orders where kind='second'),'123456789012')$$,'Failed payment accepts bank UTR');
select is((select status from public.payment_orders where id=(select id from upi_orders where kind='second')),'submitted','UTR requires bank review');
select throws_ok($$select public.submit_payment_utr((select id from upi_orders where kind='second'),'ABC123')$$,'P0001','Enter the 12-digit bank UTR','UTR must be 12 digits');
reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.report_payment_result((select id from upi_orders where kind='second'),'Status=SUCCESS&txnId=STOLEN01')$$,'P0001','Order not found','Other user cannot report');
select is((select count(*) from public.payment_orders),0::bigint,'Other user cannot read orders');
reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.admin_mark_payment_paid((select id from upi_orders where kind='second'),'BADUTR')$$,'P0001','Enter the 12-digit bank UTR','Owner must supply valid bank UTR');
select lives_ok($$select public.admin_mark_payment_paid((select id from upi_orders where kind='second'),'123456789012')$$,'Owner approves submitted payment');
select lives_ok($$select public.admin_mark_payment_paid((select id from upi_orders where kind='second'),'123456789012')$$,'Owner approval idempotent');
select ok((select verified_at is not null and verification_source='admin' from public.payment_orders where id=(select id from upi_orders where kind='second')),'Verification provenance stored');
select lives_ok($$select public.admin_revoke_payment((select id from upi_orders where kind='first'),'Bank did not receive payment')$$,'Revoke removes purchased time');
select is((select ends_at-starts_at from public.subscriptions where order_id=(select id from upi_orders where kind='second')),interval '7 days','Revoke subtracts first order duration from stacked renewal');
reset role;
select ok(exists(select 1 from private.used_payment_utrs where utr='NEW00001'),'Revoked transaction remains blocked');
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
insert into upi_orders select 'third',(x->>'id')::uuid,x->>'reference' from(select public.create_payment_order((select id from public.plans where code='trial'))x)q;
select throws_ok($$select public.submit_payment_utr((select id from upi_orders where kind='third'),'123456789012')$$,'P0001','transaction id already used','UTR cannot be reused');
reset role;
update public.payment_orders set created_at=now()-interval '3 hours' where id=(select id from upi_orders where kind='third');
set local role authenticated;
select is(public.report_payment_result((select id from upi_orders where kind='third'),'Status=SUCCESS&txnId=NEW00003'),'pending','Two-hour auto limit');
reset role;
update public.payment_orders set created_at=now()-interval '25 hours' where id=(select id from upi_orders where kind='third');
select private.cancel_stale_payment_orders();
select is((select status from public.payment_orders where id=(select id from upi_orders where kind='third')),'cancelled','24-hour job cancels unpaid');
set local role authenticated;
select lives_ok($$select public.submit_payment_utr((select id from upi_orders where kind='third'),'123456789013')$$,'Cancelled order can be submitted with bank UTR');
reset role;
set local role service_role;
select lives_ok($$select public.provider_payment_update((select id from upi_orders where kind='third'),'SUCCESS',1,'123456789013','bank-alert-1')$$,'Mismatch recorded instead of activated');
reset role;
select is((select status from public.payment_orders where id=(select id from upi_orders where kind='third')),'review','Amount mismatch requires review');
set local role service_role;
select lives_ok($$select public.provider_payment_update((select id from upi_orders where kind='third'),'SUCCESS',4900,'123456789013','bank-alert-1')$$,'Provider exact amount activates');
select lives_ok($$select public.provider_payment_update((select id from upi_orders where kind='third'),'SUCCESS',4900,'123456789013','bank-alert-1')$$,'Provider retry idempotent');
reset role;
select is((select count(*) from public.subscriptions where order_id=(select id from upi_orders where kind='third')),1::bigint,'Provider does not double grant');

-- Evidence must survive activation failures, including an unrelated downstream trigger.
set local role authenticated;
insert into upi_orders select 'failure-test',(x->>'id')::uuid,x->>'reference' from(select public.create_payment_order((select id from public.plans where code='trial'))x)q;
reset role;
create function pg_temp.block_activation()returns trigger language plpgsql as $begin raise exception 'Simulated subscription write failure';end$;
create trigger test_activation_failure before insert on public.subscriptions for each row execute function pg_temp.block_activation();
set local role authenticated;
select is(public.report_payment_result((select id from upi_orders where kind='failure-test'),'Status=SUCCESS&txnId=EVIDENCE01'),'pending','Activation error does not lose report');
select is((select raw_response from public.payment_orders where id=(select id from upi_orders where kind='failure-test')),'Status=SUCCESS&txnId=EVIDENCE01','Raw result survives exception subtransaction');
select is((select client_status from public.payment_orders where id=(select id from upi_orders where kind='failure-test')),'SUCCESS','Parsed status survives exception subtransaction');
select is((select result_note from public.payment_orders where id=(select id from upi_orders where kind='failure-test')),'Simulated subscription write failure','Activation failure explains pending result');
reset role;
drop trigger test_activation_failure on public.subscriptions;
update public.payment_settings set activation_mode='manual';
set local role authenticated;
select is(public.report_payment_result((select id from upi_orders where kind='failure-test'),'Status=SUCCESS&txnId=EVIDENCE01'),'review','Manual mode enters explicit review');
reset role;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($select public.admin_reject_payment((select id from upi_orders where kind='failure-test'),'No matching bank credit')$,'Owner rejects review');
select is((select status from public.payment_orders where id=(select id from upi_orders where kind='failure-test')),'rejected','Rejected terminal status');
select throws_ok($select public.admin_mark_payment_paid((select id from upi_orders where kind='failure-test'),'123456789014')$,'P0001','Order closed','Rejected order cannot be reactivated');
reset role;
select ok(exists(select 1 from private.used_payment_utrs where utr='EVIDENCE01'),'Rejected transaction remains reserved');
select * from finish();
rollback;
